fn test_ecr_repositories_shadow_describe_repositories_signed(client: &aws_sdk_ecr::Client) -> Test {
    Test {
        call: Call {
            op: "DescribeRepositories",
            params: scenario::map(vec![
                ("repositoryNames", scenario::list(vec![scenario::name("repo")])),
            ]),
            export: Vec::new(),
            invoke: {
                let client = client.clone();
                scenario::invoker(move |b| {
                    let client = client.clone();
                    Box::pin(async move {
                        let capture = scenario::Capture::new();
                        let request = client
                            .describe_repositories()
                            .repository_names(b.string("repositoryNames[0]")?)
                            .customize()
                            .interceptor(capture.clone());
                        Ok(scenario::observe(request.send().await, &capture))
                    })
                })
            },
        },
        assert: vec![
            scenario::response_field(vec![
                scenario::non_empty("$.repositories[0].createdAt"),
                scenario::non_empty("$.repositories[0].registryId"),
                scenario::equals("$.repositories[0].repositoryArn", scenario::context("repo.arn")),
                scenario::equals("$.repositories[0].repositoryName", scenario::name("repo")),
                scenario::matches("$.repositories[0].repositoryUri", "/.+-ecr-repositories-shadow-repo$"),
            ]),
        ],
    }
}

